<?php $esc=function($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');};$asset=function($f){return $f?base_url().'upload/qms_report_assets/'.rawurlencode(basename($f)):'';};$prepared=$settings&&isset($settings->risk_prepared_by)&&$settings->risk_prepared_by!==''?$settings->risk_prepared_by:$preparedBy;$approved=$settings&&isset($settings->risk_approved_by)?$settings->risk_approved_by:'';?><!doctype html><html><head><meta charset="utf-8"><title>Risk Registry</title><style>@page{size:landscape;margin:12mm}body{font-family:Arial;font-size:10px}.toolbar{margin-bottom:10px}.letterhead{width:100%;height:auto;max-height:100px;object-fit:contain}.title{text-align:center;font-size:22px;font-weight:bold;margin:8px}.office{font-size:13px;font-weight:bold;margin:10px 0 25px}table{border-collapse:collapse;width:100%;table-layout:fixed}th,td{border:1px solid #222;padding:5px;vertical-align:top;word-wrap:break-word}th{background:#c7d8eb;text-align:center}.group{background:#8eafd5}.center{text-align:center}.notes{margin-top:16px;line-height:1.4}.signatures{display:flex;justify-content:space-around;margin-top:35px;font-size:12px}.signature{width:34%}.line{margin-top:42px;border-top:1px solid;padding-top:3px;text-align:center;font-weight:bold}.footer{width:100%;max-height:65px;object-fit:contain;margin-top:14px}@media print{.toolbar{display:none}}</style></head><body><div class="toolbar"><button onclick="window.print()">Print / Save PDF</button></div><?php if($settings&&$settings->letterhead_file):?><img class="letterhead" src="<?=$esc($asset($settings->letterhead_file))?>"><?php endif;?><div class="title">RISK REGISTRY</div><div class="office">A. Name of Bureau/Service/Functional Division/School: <?=$esc($sectionName)?></div><h3>B. Risk Registry</h3><table><colgroup><col style="width:3%"><col style="width:15%"><col style="width:14%"><col style="width:14%"><col style="width:4%"><col style="width:4%"><col style="width:4%"><col style="width:11%"><col style="width:10%"><col style="width:7%"><col style="width:3%"><col style="width:3%"><col style="width:4%"></colgroup><tr><th rowspan="2" class="group">No</th><th colspan="3" class="group">Risk Identification</th><th colspan="3" class="group">Risk Analysis &amp; Risk Evaluation</th><th colspan="3" class="group">Risk Treatment</th><th colspan="3" class="group">Target Risk Assessment</th></tr><tr><th>Declared Process &amp; Risk Description</th><th>Risk Causes &amp; Consequences</th><th>Current controls</th><th>L</th><th>I</th><th>RR</th><th>Action/Response</th><th>Person/Office Responsible</th><th>Target Date</th><th>L</th><th>I</th><th>RR</th></tr><?php foreach($entries as $i=>$x):?><tr><td><?=$i+1?></td><td><?=$esc($x->declared_process)?></td><td><?=$esc($x->risk_causes_consequences)?></td><td><?=$esc($x->current_controls)?></td><td><?=$x->likelihood?></td><td><?=$x->impact?></td><td><?=$x->risk_rating?></td><td><?=$esc($x->action_response)?></td><td><?=$esc($x->person_responsible)?></td><td><?=$esc($x->target_date)?></td><td><?=$x->target_likelihood?></td><td><?=$x->target_impact?></td><td><?=$x->target_risk_rating?></td></tr><?php endforeach;?></table><div class="signatures"><div class="signature">Prepared by:<div class="line"><?=$esc($prepared)?></div>Process Owner</div><div class="signature">Approved by:<div class="line"><?=$esc($approved)?></div>Division Chief / Authorized Approver</div></div><?php if($settings&&$settings->footer_file):?><img class="footer" src="<?=$esc($asset($settings->footer_file))?>"><?php endif;?></body></html>
